from .units import g_to_kg, kg_to_g

MAX_PARCEL_G = 20000


class Parcel:
    def __init__(self, weight_kg, skus):
        self._grams = kg_to_g(weight_kg)
        self.skus = list(skus)

    @property
    def weight_kg(self):
        return g_to_kg(self._grams)

    def add(self, weight_kg, sku):
        self._grams += kg_to_g(weight_kg)
        self.skus.append(sku)


def split_parcels(order):
    """First-fit decreasing. A unit heavier than the limit travels alone."""
    units = []
    for item in order.items:
        units.extend((kg_to_g(item.weight_kg), item.sku) for _ in range(item.qty))
    units.sort(key=lambda unit: (-unit[0], unit[1]))
    parcels = []
    for grams, sku in units:
        for parcel in parcels:
            if parcel._grams + grams <= MAX_PARCEL_G:
                parcel.add(g_to_kg(grams), sku)
                break
        else:
            parcels.append(Parcel(g_to_kg(grams), [sku]))
    return parcels

