"""Weight helpers. Weights are kilograms written as decimal strings with three decimals."""
import re

MAX_TOTAL_G = 2**31 - 1

_INPUT = re.compile(r"([0-9]+)(?:\.([0-9]+))?")


class WeightError(ValueError):
    """Invalid weight, or a total over the carrier limit."""


def _invalid(value):
    return WeightError(f"invalid weight: {value!r}")


def _to_g(value):
    """Exact grams (int) for an accepted kg string, rounding half to even."""
    if not isinstance(value, str):
        raise _invalid(value)
    match = _INPUT.fullmatch(value)
    if match is None:
        raise _invalid(value)
    whole, frac = match.group(1), match.group(2) or ""
    grams = int(whole) * 1000 + int((frac[:3]).ljust(3, "0"))
    rest = frac[3:]
    if rest:
        first = int(rest[0])
        if first > 5 or (first == 5 and (any(c != "0" for c in rest[1:]) or grams % 2 == 1)):
            grams += 1
    return grams


def g_to_kg(grams):
    if isinstance(grams, bool) or not isinstance(grams, int) or grams < 0:
        raise _invalid(grams)
    return f"{grams // 1000}.{grams % 1000:03d}"


def normalize_kg(value):
    return g_to_kg(_to_g(value))


def kg_to_g(value):
    return _to_g(value)
EOF
